import sqlite3
import uuid
from flask import Flask, request, jsonify, g, render_template_string, abort

app = Flask(__name__)
DATABASE = 'db.sqlite3'


def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db


@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()


def init_db():
    with app.app_context():
        db = get_db()
        db.executescript('''
            CREATE TABLE IF NOT EXISTS recipes (
                id TEXT PRIMARY KEY,
                title TEXT NOT NULL,
                ingredients TEXT NOT NULL,
                instructions TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS comments (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                recipe_id TEXT NOT NULL,
                comment TEXT NOT NULL,
                FOREIGN KEY (recipe_id) REFERENCES recipes(id)
            );
            CREATE TABLE IF NOT EXISTS ratings (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                recipe_id TEXT NOT NULL,
                rating INTEGER NOT NULL,
                FOREIGN KEY (recipe_id) REFERENCES recipes(id)
            );
        ''')
        db.commit()


def recipe_to_dict(row, db):
    recipe_id = row['id']
    comments = db.execute(
        'SELECT comment FROM comments WHERE recipe_id = ?', (recipe_id,)
    ).fetchall()
    ratings = db.execute(
        'SELECT rating FROM ratings WHERE recipe_id = ?', (recipe_id,)
    ).fetchall()
    avg = None
    if ratings:
        avg = sum(r['rating'] for r in ratings) / len(ratings)
    return {
        'id': recipe_id,
        'title': row['title'],
        'ingredients': row['ingredients'].split('\n') if row['ingredients'] else [],
        'instructions': row['instructions'],
        'comments': [{'comment': c['comment']} for c in comments],
        'avgRating': avg,
    }


OVERVIEW_TEMPLATE = '''
<!DOCTYPE html>
<html>
<head><title>Recipes</title></head>
<body>
<h1>Recipe Overview</h1>
<h2>Recent Recipes</h2>
<ul>
{% for r in recent %}
<li><a href="/recipes/{{ r.id }}">{{ r.title }}</a></li>
{% endfor %}
</ul>
<h2>Top Rated Recipes</h2>
<ul>
{% for r in top %}
<li><a href="/recipes/{{ r.id }}">{{ r.title }}</a> ({{ r.avg }})</li>
{% endfor %}
</ul>
</body>
</html>
'''

RECIPE_TEMPLATE = '''
<!DOCTYPE html>
<html>
<head><title>{{ recipe.title }}</title></head>
<body>
<h1>{{ recipe.title }}</h1>
<h2>Ingredients</h2>
<ul>
{% for i in recipe.ingredients %}
<li>{{ i }}</li>
{% endfor %}
</ul>
<h2>Instructions</h2>
<p>{{ recipe.instructions }}</p>
<h2>Average Rating</h2>
<p>{{ recipe.avgRating if recipe.avgRating is not none else "No ratings yet" }}</p>
<h2>Comments</h2>
<ul>
{% for c in recipe.comments %}
<li>{{ c.comment }}</li>
{% endfor %}
</ul>
</body>
</html>
'''


@app.route('/recipes', methods=['GET'])
def recipes_overview():
    try:
        db = get_db()
        rows = db.execute('SELECT * FROM recipes ORDER BY rowid DESC').fetchall()
        recent = [{'id': r['id'], 'title': r['title']} for r in rows[:10]]

        all_recipes = []
        for r in rows:
            ratings = db.execute(
                'SELECT rating FROM ratings WHERE recipe_id = ?', (r['id'],)
            ).fetchall()
            if ratings:
                avg = sum(x['rating'] for x in ratings) / len(ratings)
            else:
                avg = 0
            all_recipes.append({'id': r['id'], 'title': r['title'], 'avg': round(avg, 2)})
        all_recipes.sort(key=lambda x: x['avg'], reverse=True)
        top = all_recipes[:10]

        return render_template_string(OVERVIEW_TEMPLATE, recent=recent, top=top)
    except Exception:
        return 'Server error', 500


@app.route('/recipes/upload', methods=['POST'])
def upload_recipe():
    data = request.get_json(silent=True)
    if not data:
        return jsonify({'error': 'Invalid input'}), 400
    title = data.get('title')
    ingredients = data.get('ingredients')
    instructions = data.get('instructions')
    if not title or not isinstance(title, str):
        return jsonify({'error': 'Invalid input'}), 400
    if not ingredients or not isinstance(ingredients, list) or not all(isinstance(i, str) for i in ingredients):
        return jsonify({'error': 'Invalid input'}), 400
    if not instructions or not isinstance(instructions, str):
        return jsonify({'error': 'Invalid input'}), 400

    db = get_db()
    recipe_id = str(uuid.uuid4())
    db.execute(
        'INSERT INTO recipes (id, title, ingredients, instructions) VALUES (?, ?, ?, ?)',
        (recipe_id, title, '\n'.join(ingredients), instructions)
    )
    db.commit()
    row = db.execute('SELECT * FROM recipes WHERE id = ?', (recipe_id,)).fetchone()
    return jsonify(recipe_to_dict(row, db)), 201


@app.route('/recipes/<recipe_id>', methods=['GET'])
def get_recipe(recipe_id):
    db = get_db()
    row = db.execute('SELECT * FROM recipes WHERE id = ?', (recipe_id,)).fetchone()
    if row is None:
        return 'Recipe not found', 404
    recipe = recipe_to_dict(row, db)
    return render_template_string(RECIPE_TEMPLATE, recipe=recipe)


@app.route('/recipes/<recipe_id>/comments', methods=['POST'])
def add_comment(recipe_id):
    db = get_db()
    row = db.execute('SELECT * FROM recipes WHERE id = ?', (recipe_id,)).fetchone()
    if row is None:
        return jsonify({'error': 'Recipe not found'}), 404
    data = request.get_json(silent=True)
    if not data:
        return jsonify({'error': 'Invalid input'}), 400
    comment = data.get('comment')
    if not comment or not isinstance(comment, str):
        return jsonify({'error': 'Invalid input'}), 400
    db.execute('INSERT INTO comments (recipe_id, comment) VALUES (?, ?)', (recipe_id, comment))
    db.commit()
    return jsonify({'message': 'Comment added successfully'}), 201


@app.route('/recipes/<recipe_id>/ratings', methods=['POST'])
def add_rating(recipe_id):
    db = get_db()
    row = db.execute('SELECT * FROM recipes WHERE id = ?', (recipe_id,)).fetchone()
    if row is None:
        return jsonify({'error': 'Recipe not found'}), 404
    data = request.get_json(silent=True)
    if not data:
        return jsonify({'error': 'Invalid input'}), 400
    rating = data.get('rating')
    if not isinstance(rating, int) or isinstance(rating, bool) or rating < 1 or rating > 5:
        return jsonify({'error': 'Invalid input'}), 400
    db.execute('INSERT INTO ratings (recipe_id, rating) VALUES (?, ?)', (recipe_id, rating))
    db.commit()
    return jsonify({'message': 'Rating added successfully'}), 201


if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=5000)
